INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q1', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 0 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '한 나라의 그룹 (교구·단체·개별 그룹)은 독립적으로 등록할 수 있나요, 아니면 주교회의의 승인이나 통합 등록이 필요한가요?', '한 나라의 각 교구·단체·개별 그룹은 등록시스템을 통해 독립적으로 등록할 수 있으며, 반드시 주교회의를 통해 통합 등록해야 하는 것은 아닙니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q2', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 1 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '그룹 규모별로 필요한 리더와 부리더의 수는 몇 명이며, 추가 리더를 추후 지정할 수 있나요? 또한 그룹 리더와 하위그룹 리더가 열람·관리할 수 있는 정보의 범위는 어디까지인가요?', '단일그룹(Single Group)과 대규모그룹(Macrogroup)은 각각 그룹 대표 1명과 부대표 1명으로 구성됩니다. 그룹 규모가 크거나 서울 도착 출발 일정·패키지가 서로 다른 경우에는 대규모그룹 내에 하위그룹(Subgroup)을 구성할 수 있습니다. 하위그룹은 대규모그룹 대표의 계정과 별도의 계정으로 생성할 수 있으며, 이 경우 하위 그룹에도 대표 1명과 부대표 1명을 지정합니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q3', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 2 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '대규모그룹(Macrogroup)에서 한 가족을 하나의 하위 그룹(Subgroup)으로 인정할 수 있나요? 최소 인원 기준은 무엇인가요?
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q4', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 3 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '저희 교구(비카리아) 소속으로 등록된 대표자가 다른 나라에서 오는 경우(예: 해외 거주 본당 신자의 자녀가 부모와 동행하고자 하는 경우), 저희 조직 아래로 등록하는 것이 맞나요?', '해외에 거주하거나 다른 나라에서 출발하는 참가자라도, 귀 교구(비카리아) 그룹의 일원으로 함께 참가하고 그룹 리더의 인솔과 관리 아래 활동할 예정이라면 해당 그룹에 포함하여 등록하실 수 있습니다. 예를 들어, 해외에 거주하는 본당 신자의 자녀가 부모와 함께 귀 교구 그룹에 참가하는 경우에도 같은 그룹으로 등록할 수 있습니다.' FROM qa_item WHERE question_no = 'Q4' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q5', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 4 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '국제기구나 여러 국가·교구로 구성된 단체의 경우, 동일한 그룹 또는 대규모그룹(Macrogroup)안에 서로 다른 날짜·시간·항공편·교통수단으로 도착하거나 출발할 경우 등록과 패키지 선택은 어떻게 진행해야 하나요?', '소속 국제기구 또는 교구의 이름으로 하나의 대규모그룹(Macrogroup)을 등록한 후, 동일한 패키지와 서울 체류 일정을 가진 참가자들끼리 하위그룹(Subgroup)을 구성하여 등록하시면 됩니다. 각 하위그룹은 최대 150명까지 등록할 수 있습니다.' FROM qa_item WHERE question_no = 'Q5' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q6', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 5 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '사제, 부제, 수도자는 일반 순례자 그룹의 일원으로 등록하나요, 아니면 별도로 등록해야 하나요? 사제가 대규모그룹(Macrogroup)에 속한 경우에도 동일한 방식으로 등록하나요?', '사제, 부제, 수도자 모두 일반 순례자 그룹의 참가자로 등록합니다. 대규모그룹(Macrogroup)의 경우에도 실제 순례자 등록은 하위그룹(Subgroup) 단위로 이루어지므로, 자신이 속한 하위그룹에 포함하여 등록합니다. 사제와 부제는 일반 순례자와 달리 신분 확인 및 성직자 관련 준비를 위해 개인 정보를 별도로 입력해야 하며, 그룹 대표가 정보를 취합하여 등록 시스템에 입력합니다.' FROM qa_item WHERE question_no = 'Q6' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q7', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 6 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '저희는 국제 그룹의 코디네이터입니다. 하나의 대규모그룹(Macrogroup)을 만들고 국가별로 하위그룹(Subgroup)을 두는 것이 나을까요, 아니면 국가별로 각각 대규모그룹을 만들고 그 안에서 패키지별 하위그룹을 두는 것이 나을까요?', '국제 그룹의 등록 구조는 그룹의 운영 방식과 국가별 담당자의 역할을 고려하여 선택하시는 것이 좋습니다. 국제 코디네이터가 전체 그룹을 통합 관리하고 국가별 담당자가 각 하위그룹을 관리하려는 경우에는, 하나의 매크로그룹 아래 국가별 하위그룹을 구성하는 방식을 고려할 수 있습니다. 반면, 국가별로 참가자 관리와 등록·납부를 독립적으로 진행하는 경우에는 국가별로 각각 대규모그룹을 구성하는 방식이 관리에 더 편리할 수 있습니다. 패키지별 하위그룹 구성 여부는 각 국가의 참가자 구성과 패키지 선택에 따라 검토해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q7' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q8', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 7 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '단일그룹(Single Group)의 순례자 수가 늘어나면 자동으로 대규모그룹 (Macrogroup)으로 전환되나요?', '단일그룹(Single Group)의 순례자 수가 늘어나더라도 자동으로 대규모그룹(Macrogroup)으로 전환되지는 않습니다. 단일그룹은 최대 150명까지 등록할 수 있으므로, 참가 인원이 150명을 초과할 가능성이 있다면 처음부터 대규모그룹으로 등록해야 합니다. 그룹 유형은 등록을 시작할 때 선택하며, 등록을 시작한 이후에는 변경할 수 없습니다.' FROM qa_item WHERE question_no = 'Q8' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q9', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 8 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '단일그룹(Single Group)과 대규모그룹(Macrogroup)의 차이가 단순히 인원 수만이 아니라고 하셨는데, 대규모그룹이 되기 위해 충족해야 하는 조건(특성)과 대규모그룹으로 등록했을 때의 장점은 무엇입니까?', '단일그룹(Single Group)과 대규모그룹(Macrogroup)의 차이는 참가 인원뿐 아니라, 참가 일정과 패키지 구성 및 등록 관리 방식에 있습니다. 단일그룹은 최대 150명까지 별도의 하위그룹(Subgroup) 없이 하나의 그룹으로 등록하는 방식으로, 모든 참가자의 참가 일정과 패키지가 동일한 경우에 적합합니다. 대규모그룹은 최대 5,000명까지 등록할 수 있으며, 참가 일정이나 패키지가 서로 다른 참가자들을 하위그룹으로 나누어 관리할 수 있습니다. 각 하위그룹은 동일한 패키지와 도착일·출발일을 가진 참가자들로 구성합니다. 대규모그룹의 장점은 하나의 조직 아래 여러 하위그룹을 두면서도, 하위그룹별로 등록·정보 수정·결제를 독립적으로 진행할 수 있다는 점입니다. 따라서 그룹 규모뿐 아니라 참가 일정과 패키지의 다양성, 하위그룹별 관리 필요성을 고려하여 등록 방식을 선택하시면 됩니다' FROM qa_item WHERE question_no = 'Q9' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q10', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 9 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '한국까지는 개별적으로 이동하지만 동일한 그룹에 속한 사람들은 별도의 하위그룹(Subgroup)을 만들어야 하나요?', '한국까지 개별적으로 이동하더라도, 대회 기간 중 동일한 일정에, 동일한 패키지를 이용하여, 동일한 그룹 리더의 인솔과 관리 아래 활동할 예정이라면 별도의 하위그룹을 구성하지 않고 같은 그룹으로 등록하실 수 있습니다. 다만, 참가자별로 선택하는 패키지나 참가 일정이 다른 경우에는 하위그룹 구성이 필요할 수 있으므로, 등록시스템의 세부 기준을 확인해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q10' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q11', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 10 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '저희가 150명 미만의 단일그룹(Single Group)인데 서로 다른 두 가지 교통수단으로 도착할 경우, 같은 그룹으로 등록하고 두 곳에서 각각 픽업 받을 수 있나요?', '150명 미만의 단일그룹(Single Group)이 서로 다른 교통수단으로 도착하더라도, 동일한 일정과 패키지로 같은 그룹 리더의 인솔과 관리 아래 참가할 예정이라면 같은 그룹으로 등록하실 수 있습니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q12', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 11 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교구당 구성할 수 있는 대규모그룹(Macrogroup)의 수에 제한이 있나요?', '대규모그룹(Macrogroup) 수의 제한은 없으며, 그룹 내 인원만 5,000명 이하로 제한합니다.' FROM qa_item WHERE question_no = 'Q12' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q13', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 12 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '등록 과정에서 주교회의는 어떤 역할을 하나요? 모든 그룹이 주교회의 청소년부의 승인을 받아야 하나요?', '각 주교회의는 등록 과정에서의 역할을 자율적으로 결정할 수 있습니다. 조직위는 한 국가의 모든 그룹이 등록하기 위해 반드시 해당 주교회의 청소년 담당 부서의 승인을 받도록 요구하지 않습니다.' FROM qa_item WHERE question_no = 'Q13' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q14', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 13 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '저희 그룹은 교구대회(Days in the Dioceses)에 참가하지만, 자체 프로그램을 준비하고(숙소도 자체적으로 마련) LOC의 물류 지원이 필요 없습니다. 등록 포털에서 교구대회 참가 여부를 ''예''로 체크해야 하나요, ''아니오''로 체크해야 하나요?', '교구대회 준비 및 운영상의 참조를 위해 참가여부를 ''예''로 체크해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q14' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q15', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 14 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '등록이 시작되는 시점부터 각 국가 담당자가 등록 관련 문의를 해결할 수 있도록 직접적인 지원이 제공되나요? 또한 단계별 안내가 담긴 전체 영상을 제공해주시나요?', '각국 담당자들이 등록 관련 문의에 원활하게 대응할 수 있도록 지원 방안과 안내 자료를 준비하고 있습니다. 담당자 대상 직접 지원 방식과 단계별 등록 절차를 설명하는 전체 영상의 제공 여부는 현재 내부적으로 검토·논의 중이며, 구체적인 내용과 제공 일정은 확정되는 대로 안내드리겠습니다.' FROM qa_item WHERE question_no = 'Q15' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q16', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 15 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '그룹 등록은 전액 결제가 완료된 후에만 공식 확정(구역, 숙소 등 배정 포함)되나요, 아니면 등록 포털에 기본 정보를 처음 제출한 시점에 이미 확정되나요?', '그룹 등록은 참가 분담금의 전액 결제가 완료된 후에만 공식 확정됩니다.' FROM qa_item WHERE question_no = 'Q16' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q17', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 16 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '사제 등록 및 인증을 위해 필요한 서류는 무엇인가요? Celebret, 사목허가증 및 Good Standing 증명서 등이 필요한지 궁금합니다. 또한 수도회 소속 사제의 경우 관구장의 증명서로 충분한지, 아니면 교구장 주교의 증명서가 필요한지도 안내 부탁드립니다.', '사제는 소속 그룹의 일원으로 등록하며, 사제 신분 확인을 위해서는 신분증 사진, 소속 교구 직권자가 발급한 사제 신분증명서, 미성년자 및 취약 성인 보호 확인서를 제출해야 합니다. 수도회 소속 사제의 경우에는 소속 관구장의 증명서를 제출하시면 됩니다.' FROM qa_item WHERE question_no = 'Q17' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q18', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 17 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '등록은 언제 시작되나요? 대규모그룹(Macrogroup)의 순례자 등록을 순차적으로 나눠서 할 수 있나요 ? 아니면 한번에 완료해야 하나요 ?', '온라인 등록은 10월 23일에 시작할 예정이며, 대규모그룹(Macrogroup)의 전체 등록을 한 번에 진행하실 필요는 없습니다. 등록시스템의 ''임시 저장(Save as draft)'' 기능을 이용하여 입력한 내용을 저장한 후, 추후 추가 정보를 입력하거나 기존 내용을 수정하실 수 있습니다. 필요한 등록 정보를 모두 입력하고 확인한 뒤 결제를 진행해 주시기 바랍니다. 또한 대규모그룹 내에 하위그룹(Subgroup)을 구성하여, 준비가 완료된 하위그룹부터 등록하고 나머지 그룹은 준비되는 대로 순차적으로 등록하실 수 있습니다.' FROM qa_item WHERE question_no = 'Q18' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q19', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 18 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자의 연령 기준과 참가 인원 제한은 무엇이며, 30세 이상 청년과 40~50대 이상 성인 또는 고령 동반자는 어떤 자격으로 등록해야 하나요?', 'WYD는 주로 14세부터 30세까지의 젊은이들을 중심으로 마련된 행사이지만, 참여를 원하는 모든 이들에게 열려 있으며 순례자의 참가 연령과 인원에 별도의 제한은 없습니다. 따라서 30세 이상 참가자와 40~50대 성인, 고령 동반자도 별도의 자격 구분 없이 순례자 그룹의 일원으로 등록할 수 있습니다.' FROM qa_item WHERE question_no = 'Q19' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q20', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 19 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '등록 과정에서 참가자를 추가·삭제하거나 입력 정보를 수정할 수 있나요?', '가능합니다. 결제 완료 전에는 그룹 리더가 등록시스템에서 전체 참가 인원을 늘리거나 줄일 수 있으며, 사제·부제, 장애가 있는 순례자 및 비자 신청자의 입력 정보도 수정할 수 있습니다. 결제 완료 후에는 조직위원회에 연락하여 정보 수정을 요청해 주시기 바랍니다. 다만, 참가 인원이 감소하더라도 해당 인원에 대한 참가 분담금은 환불되지 않으므로 유의해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q20' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q21', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 20 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '참가 취소 시 해당 자리를 대기자나 다른 순례자에게 양도할 수 있으며, 변경 가능한 시점과 범위는 어떻게 되나요?', '그룹 대표와 부대표를 제외한 순례자는 등록 시점이나 결제 여부와 관계없이 다른 참가자로 변경할 수 있습니다. 따라서 참가를 취소하는 순례자를 대기자나 다른 순례자로 대체하실 수 있습니다. 다만, 결제 완료 후 참가자를 대체하지 않아 그룹의 전체 참가 인원이 감소하는 경우에는, 감소한 인원에 대한 결제금액은 환불되지 않으므로 이 점을 유의해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q21' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q22', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 21 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '리더가 순례자의 정보를 잘못 입력했을 경우, 순례자 본인이 직접 수정할 수 있나요?', '순례자 본인이 등록시스템에서 자신의 정보를 직접 수정할 수는 없습니다. 개별 참가자 정보는 그룹의 대표와 부대표, 사제·부제, 장애가 있는 순례자 및 비자 발급 지원이 필요한 참가자에 한해 입력이 필요합니다. 그룹 리더가 해당 정보를 잘못 입력한 경우, 결제 완료 전에는 그룹 리더가 직접 수정할 수 있습니다. 결제 완료 후, 수정이 필요한 경우에는 조직위원회(inquiries@wydseoul.org)로 요청해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q22' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q23', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 22 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '부득이한 사정으로 WYD에 참석하지 못하게 될 경우, 어느 단계에서든 환불이 가능한가요, 아니면 모든 결제 단계가 완료되면 전혀 환불이 안 되나요?(ex.전쟁,자연재해 등)', '참가분담금은 원칙적으로 환불되지 않습니다. 다만 비자 발급이 거부되어 이를 확인할 수 있는 증빙 서류를 제출하신 경우에 한해 예외적으로 환불해 드립니다. 환불은 대회 종료 후에 진행되며, 관련 수수료 등을 제외한 금액이 지급됩니다. 현재 비자 미발급 사유 외 전쟁이나 자연재해 등 사유는 환불 대상에 포함되어 있지 않지만, 해당 사유들도 신중히 검토 하겠습니다.' FROM qa_item WHERE question_no = 'Q23' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q24', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 23 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '해외송금 및 회계 처리를 위해 공식 인보이스 또는 직인이 포함된 청구서를 발급받을 수 있나요?', '현재 기준으로는 별도의 정형화된 인보이스를 발급하지 않고 있습니다. 다만 국가 및 단체마다 해외 송금에 관한 법적·회계적 요건이 다르다는 점을 이해하고 있으며, 조직위는 조직위로의 직접 납부 방식을 전제로 납부에 필요한 서류를 어떤 형태로 제공할 수 있을지 검토하고 있습니다. 검토 결과는 확정되는 대로 안내 드리겠습니다.' FROM qa_item WHERE question_no = 'Q24' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q25', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 24 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '동일한 대규모그룹(Macrogroup)안에서 하위그룹(Subgroup)별로 서로 다른 패키지를 선택하고 개별 결제할 수 있나요? 일부 하위그룹의 결제 지연이 전체 대규모그룹에 미치는 영향에 대해서도 궁금합니다.', '네, 동일한 대규모그룹(Macrogroup) 안에서 하위그룹(Subgroup)별로 서로 다른 패키지를 선택하고 각각 결제할 수 있습니다. 각 하위그룹은 본 대회 참가를 위한 동일한 서울 체류 일정과 패키지를 이용하는 순례자들로 구성해 주시기 바랍니다. 결제는 하위그룹별로 진행되므로, 일부 하위그룹의 결제가 지연되더라도 다른 하위그룹이나 매크로 그룹의 등록 및 결제에는 영향을 미치지 않습니다.' FROM qa_item WHERE question_no = 'Q25' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q26', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 25 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '등록 및 각 패키지의 결제 일정과 마감일은 어떻게 되나요? 첫 결제, 분할 납부, 잔금 및 보험료 등 각 항목별 납부 기한을 안내받을 수 있나요?', '결제는 등록시스템이 오픈된 날부터 가능합니다. 결제 기한은 패키지 유형과 결제 방법에 따라 다음과 같습니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q27', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 26 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '참가비는 얼마이며 어떤 방법과 통화로 결제할 수 있나요? 달러로만 가능한가요, 아니면 유로로도 결제할 수 있나요 ? ‘기타 결제 방법’에는 무엇이 포함되며, 하나의 그룹에 대해 서로 다른 기관이 나누어 결제하는 것도 가능한가요?', '참가비는 공식 홈페이지에서 확인하실 수 있습니다. 결제는 대한민국에서는 원화, 그 외 국가에서는 미국 달러로 진행됩니다. 결제창에서 ''자국통화결제''를 선택하시면 주요 국가의 통화로도 결제하실 수 있으며, 이때 발생하는 추가 수수료는 결제자가 부담합니다. 결제 수단은 다음과 같습니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q28', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 27 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '참가분담금(Participation Contribution)과 연대기금(Solidarity Fund)은 반드시 납부해야 하는 의무 사항인가요? 설문 결과에 따르면 많은 그룹이 재정 지원이 필요한데도 등록비 외에 추가로 납부해야 하는 상황이라, 참가분담금이 정말 의무인지 궁금합니다. 또한 연대기금을 특정 국가나 지역의 순례자 지원을 위해 지정할 수 있는지도 궁금합니다.', '세계청년대회 참가 자체에는 비용이 들지 않습니다. 다만 ''등록 참가자''로 참가하시려면 참가분담금을 납부하셔야 합니다. 분담금을 납부한 등록 참가자는 원하는 패키지를 선택하여 숙박, 식사, 이동수단, 보험, 순례자 키트를 제공받습니다. 등록하지 않고 참가하시는 경우에는 이러한 패키지가 제공되지 않습니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q29', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 28 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '각 패키지별 등록·참가 비용은 얼마이며, 매크로그룹 규모, 조기 또는 일시불 결제 등에 따른 할인 혜택이 있나요? 또한 미성년자에게도 성인과 동일한 참가비가 적용되는지, 별도의 할인이나 재정 지원이 있는지도 궁금합니다.', '패키지별 참가분담금은 공식 홈페이지에서 확인하실 수 있으며, 연령과 관계없이 모든 순례자에게 동일하게 적용됩니다. 미성년자, 단체 규모, 조기 결제 등에 따른 할인은 운영하지 않습니다. 대신 조직위원회는 패키지별 참가분담금을 합리적인 범위에서 최소한의 수준으로 책정하여 모든 순례자가 참가할 수 있도록 노력했습니다.' FROM qa_item WHERE question_no = 'Q29' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q30', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 29 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '연대기금 지원을 받을 수 있는 국가·그룹·개별 순례자의 자격 요건은 무엇이며, 신청은 어떤 절차와 경로(조직위원회, DLFL, 웹사이트, 이메일 등)를 통해 이루어지나요? 대규모그룹 전체가 아닌 일부 순례자만 지원을 신청하는 것도 가능한가요?', '조직위는 현재 교황청 평신도가정생명부와 협의하여 연대기금의 자격 요건과 신청 절차를 검토하고 있습니다. 자격 요건 및 신청 방법 등 세부 사항은 확정되는 대로 안내해 드리겠습니다.' FROM qa_item WHERE question_no = 'Q30' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q31', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 30 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '주교회의 대표들이 온라인 등록 시스템의 ''백오피스''에 접근하여 자국에서 등록한 그룹과 그룹 리더 현황을 확인할 수 있는 관리 기능도 제공되나요? 지난 10년간의 모든 WYD에서는 이것이 가능했습니다.', '주교회의 대표는 등록시스템 백오피스 접근 및 열람 (읽기 전용) 권한을 DLFL에게 요청할 수 있습니다. 이를 통해, 해당 국가의 등록 현황을 확인할 수 있습니다.' FROM qa_item WHERE question_no = 'Q31' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q32', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 31 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '주교의 등록 절차 및 교리교육 참여를 위한 별도 등록 절차가 있는지 안내 부탁드립니다. 또한 주교들의 숙소 유형에 따른 체크인 절차 및 성직자용 물품 수령에 대해 안내해 주십시오.', '주교 역시 등록시스템(주교)을 통해 등록합니다. 그리고 교리교육을 담당할 주교는 DLFL에서 선정하여 관리할 것입니다. 조직위원회가 지정한 호텔에 머무는 주교들의 체크인은 해당 호텔에서 진행할 예정이고, 물품 수령 역시 호텔에서 할 수 있습니다. 그외 숙소를 이용하는 주교들의 체크인과 물품 수령 관련한 사항은 현재 논의 중에 있습니다.' FROM qa_item WHERE question_no = 'Q32' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q33', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 32 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '주교는 홈스테이와 호텔 중 숙박 유형을 선택할 수 있나요? 홈스테이를 선택할 수 있다면 청년 순례자에게 우선 배정하지 않고 주교에게도 선택권을 제공하는 이유는 무엇인가요? 또한 LOC가 주교에게 제공하는 호텔의 비용 부담 여부와 객실 유형(1인실 등)은 어떻게 되나요?', '주교는 호텔/홈스테이/동반그룹과 함께 숙박/개별 숙박 중 선택할 수 있습니다. 이는 주교의 상황에 맞게 선택을 할 수 있도록 배려한 것입니다. 호텔 숙박 비용은 주교 본인이 부담합니다. 그리고, 1인실이 기본적으로 배정될 예정입니다.' FROM qa_item WHERE question_no = 'Q33' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q34', s.id, t.id, NULL, 33 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '2027년 K-ETA 적용 대상과 면제 국가는 어떻게 되며, 개인 또는 그룹 단위로 신청할 수 있나요?', '현재 2026년 12월 31일까지의 K- ETA 적용나라는 88개국, K-ETA 면제 국가는 22개국입니다. 자세한 내용은
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q35', s.id, t.id, NULL, 34 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '비자 신청 시 필요한 한국 내 체류지 주소와 연락처를 LOC에서 제공하나요?', '비자 신청 시 한국 내 체류지 주소와 연락처는 조직위원회 정보를 기재하시면 됩니다. 해당 정보는 등록 시스템에서 발급되는 참가확인서에서 확인하실 수 있습니다.' FROM qa_item WHERE question_no = 'Q35' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q36', s.id, t.id, NULL, 35 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '저희 그룹에는 다양한 국적의 순례자가 있습니다. 국적별 비자 또는 K-ETA 필요 여부를 확인할 수 있는 안내 자료가 제공되나요? WYD 전용 비자가 별도로 있는지, C-3 비자의 성격과 비자 면제 대상자의 초청장 필요 여부도 궁금합니다.', '조직위원회는 별도의 비자 안내 자료를 제공하고 있지 않습니다. 국적별로 비자와 K-ETA의 필요여부가 달라지므로, https://www.visa.go.kr/ 에 들어가셔서 국가별 비자 필요여부를 확인해주시기 바랍니다. WYD 전용비자는 없습니다. C-3는 단기체류비자로 자세한 체류 정보는 정부와 협의 중으로 추후에 안내 드리겠습니다. 비자 면제 대상자에게는 초정장이 필요하지 않습니다.' FROM qa_item WHERE question_no = 'Q36' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q37', s.id, t.id, NULL, 36 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '조직위원회 또는 DLFL 에서 각국 한국 대사관·영사관에 WYD 개최 사실과 참가자 비자 절차를 안내하고 있나요? 비자 예약 지원, 단체 신청, 대사관과 멀리 떨어져 있는 원거리 거주 순례자를 위한 편의 (예. 일괄 신청) 및 WYD 참가 목적에 대한 별도 고려가 제공되나요?', '조직위원회는 한국 대사관과 영사관에 WYD 비자 절차에 대해 안내와 소통을 하고 있습니다. 이번 제2차 국제준비회의에도 정부와의 협의로 많은 도움을 받았습니다. 앞으로도 조직위는 한국 정부와 원만한 소통을 통해 비자 관련 절차 간소화를 진행하여 추후에 안내드릴 예정입니다.' FROM qa_item WHERE question_no = 'Q37' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q38', s.id, t.id, NULL, 37 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '비자 발급 수수료는 얼마이며, WYD 참가 순례자를 위한 수수료 면제 또는 할인 방안이 검토되고 있나요?', '비자 발급 수수료 및 WYD 참가자에 대한 수수료 면제 또는 할인 여부는 현재 관계 기관과 논의 중입니다. 관련 사항이 확정되는 대로 안내드리겠습니다.' FROM qa_item WHERE question_no = 'Q38' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q39', s.id, t.id, NULL, 38 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '학생 등 재직증명서나 급여명세서를 제출하기 어려운 순례자가 사용할 수 있는 대체 서류에 대한 지원 방안이 있나요?', '학생 및 청년 참가자 등을 위한 비자 제출서류를 현재 관계 기관과 협의하고 있습니다. 대체서류를 포함한 구체적인 제출 요건이 확정되는 대로 안내드리겠습니다.' FROM qa_item WHERE question_no = 'Q39' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q40', s.id, t.id, NULL, 39 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '국제 봉사자의 참가 비용과 비자 소지자의 장기 봉사 지원 가능 여부는 어떻게 되나요?', '국제 장기 봉사자에게 별도의 참가 비용은 없습니다. 조직위원회에서는 숙소와 평일 점심 식권, 그리고 교통비 및 식비의 일부를 제공하며, 그 외의 비용은 본인이 부담해야 합니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q41', s.id, t.id, NULL, 40 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '봉사위원회 협의 및 협업을 위한 절차 및 준비 사항은 어떻게 되나요?', '향후 공식 홈페이지에 봉사자 섹션이 마련될 예정입니다. 그 전까지는 volunteer.intl@wydseoul.org로 연락해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q41' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q42', s.id, t.id, NULL, 41 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅰ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '장기 봉사자와 단기 봉사자의 차이, 지원 자격 및 등록 절차는 무엇입니까?', '1. 장기 봉사
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q43', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 42 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '한국에서 단체 이동에 일반적으로 사용되는 버스는 몇 인승인가요? 45인승과 53인승 버스의 이용 가능 여부 및 수급 상황은 어떻게 되나요?', '한국에서 일반적으로 사용되는 단체버스는 45인승만 있으며, 행사가 열리는 기간은 휴가철로 버스 수급은 문제 없으나 비용은 평소보다 높을 수 있습니다.' FROM qa_item WHERE question_no = 'Q43' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q44', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 43 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD 기간 동안 지하철과 버스 등 대중교통의 운행 시간은 어떻게 되나요? 심야 또는 24시간 운행, 운행시간 연장 및 행사 기간의 혼잡에 대비한 증편 계획이 있나요? 또한 숙소와 주요 행사장 간 이동을 위한 교통 대책은 어떻게 마련될 예정인가요?', 'WYD 기간 동안 순례자들의 대중교통 편의 제공을 위해 서울시 및 관계기관과 지하철, 버스 등 대중교통의 증편에 대해 지속적으로 협의중에 있습니다.' FROM qa_item WHERE question_no = 'Q44' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q45', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 44 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '같은 그룹의 구성원들이 도착일과 출발일은 동일하더라도 서로 다른 항공편으로 서울에 도착하고 출발하는 것이 허용되는지 확인해주실 수 있나요?', '같은 그룹의 참가자들이 서로 다른 항공편으로 서울에 도착하고 출발하는 것은 가능합니다. 도착일과 출발일이 동일하고, 같은 패키지를 이용하며 동일한 그룹 리더의 인솔과 관리 아래 참가한다면, 항공편이 다르다는 이유만으로 별도의 하위그룹을 구성할 필요는 없습니다.' FROM qa_item WHERE question_no = 'Q45' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q46', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 45 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '부부나 가족의 경우 같은 숙소에 머물도록 요청할 수 있나요?', '부부나 가족이 함께 숙박하기를 원하시는 경우, 등록 시 동일한 그룹으로 등록해 주시기 바랍니다. 숙소 배정은 동일한 그룹의 참가자를 같은 숙소에 배정하는 것을 원칙으로 합니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q47', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 46 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자 패키지에는 어떤 형태의 숙박시설이 제공되며, 참가자가 침낭 등 별도로 준비해야 할 물품은 무엇인가요? 또한 예상 인원을 초과할 경우 추가 숙소는 어떻게 확보할 예정인가요?', '패키지에 포함된 숙박 유형은 본당· 학교·공공시설 등을 활용한 공동 숙소와 홈스테이 형태로 제공됩니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q48', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 47 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '그룹이 호텔 등 자체 숙소를 마련하는 경우 조직위원회에 숙소 정보를 알려야 하나요?', '등록 시, 자체적으로 마련한 숙소의 정보를 기재하는 란이 있습니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q49', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 48 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '그룹 리더가 WYD 전에 배정된 숙소를 미리 방문하거나 확인할 수 있나요? 또한 실제 숙소가 사전에 안내된 시설 및 조건과 다른 경우 숙소 변경을 요청할 수 있으며, 그 절차는 어떻게 되나요?', '대회 전 숙소가 배정되었다 하더라도, 숙소가 공공기관일 경우는 방문이 어려울 수 있습니다. 다만 체크인을 할 본당과 배정받은 숙소의 위치 정도는 확인하실 수는 있습니다. 하지만 역대 대회들을 보았을 때 숙소는 워낙 많은 변수가 존재하기에, 배정 이후에도 발생할 수 있는 여러 상황을 염두에 두시면 좋겠습니다. 숙소 변경을 요청할 수는 있으나, 사유 검토 후 필요시에만 변경 절차가 진행될 예정입니다.' FROM qa_item WHERE question_no = 'Q49' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q50', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 49 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '숙소는 서울 내에 배정되나요, 아니면 서울 외 지역에도 배정될 수 있나요? 주요 WYD 행사장 및 대중교통과의 접근성은 어떻게 고려되며, 각 그룹은 배정된 숙소와 담당 본당의 위치를 언제, 어떤 방식으로 안내받을 수 있나요?', '대부분의 숙소는 서울 내부에 있을 것입니다. 다만 경우에 따라 외곽에 위치한 숙소도 있을 수 있습니다. 외곽일지라도 대중교통을 이용하여 서울로 이동이 가능한 장소로 고려할 예정입니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q51', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 50 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '요즘 여러 그룹들이 항공권 예매를 시작했는데, 1일부터 10일까지의 숙박을 요청할 수 있는지 문의가 많습니다. 가능하다면 어떻게 신청하나요?', '패키지의 종류에 따라 일정이 상이합니다. 8/1-10까지의 투숙 가능 패키지는 없습니다. A1은 8/2-9 이며, A1+1은 8/1-8/9 또는 8/2-8/10 로 나뉘어져 있으니 참고 부탁드립니다.' FROM qa_item WHERE question_no = 'Q51' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q52', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 51 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '숙소 및 담당 본당은 어떤 기준으로 배정되나요? 등록 시 숙박 옵션이나 특정 본당을 선택할 수 있는지, 또는 선착순으로 배정되는지도 궁금합니다.', '순례자들은 사전에 특정 숙소 유형 및 본당을 선택할 수 없으며, 숙소 배정은 전반적인 운영 상황과 수용 인원에 따라 결정됩니다. 숙소 배정은 선착순으로 진행되지 않습니다. 다만, 등록 및 결제를 모두 완료한 그룹의 경우, 배정을 위한 정보 확인 및 절차가 원활하게 진행될 수 있으므로 가능한 한 빠른 시일 내에 등록과 결제를 완료해 주시기를 권장드립니다.' FROM qa_item WHERE question_no = 'Q52' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q53', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 52 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '두 개의 다른 그룹도 요청 시 같은 숙소에 배정받을 수 있는지 궁금합니다.', '그룹이 다를 경우, 동일 숙소 배정이 어려울 수 있으니 양해 부탁드립니다. 등록 후 해당 요청 사항을 조직위원회로 전달하여 주시면 도움드릴 수 있도록 노력하겠습니다.' FROM qa_item WHERE question_no = 'Q53' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q54', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 53 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '저희 그룹에는 영어, 프랑스어, 스페인어를 사용하는 참가자들이 있습니다. 그룹 참가자들이 언어별로 나뉘게 되나요, 아니면 숙소는 함께 지낼 수 있나요?', '동일 그룹은 동일 숙소에 배정하는 것을 원칙으로 합니다. 같은 숙소에 배정되시길 원하신다면 등록시 같은 그룹으로 등록을 부탁드립니다. 다만, 운영 상황과 수용 인원에 따라 불가피하게 동일 그룹이어도 다른 숙소에 배정될 수 있습니다. 이 경우는 최대한 인접한 숙소로 배정됩니다.' FROM qa_item WHERE question_no = 'Q54' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q55', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 54 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '행사 후에도 홈스테이 숙소가 여전히 이용 가능한가요, 아니면 주로 성당이나 체육관 같은 시설에서 숙박하게 되나요? 교통편 제약으로 100명 그룹을 2~3개 항공편으로 나눠야 할 수도 있는데, 이 경우 일부는 8월 2일 이전에 도착하게 됩니다. 이럴 때 절차는 어떻게 되나요? 그룹에 배정된 숙소로 그대로 받아들여지나요?', '선택하신 패키지에 따라 투숙일정이 정해집니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q56', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 55 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '8/2 월요일 저녁에는 어디에 묵나요? 교구에서 묵나요, 아니면 이미 서울에 있나요?', '선택하신 패키지의 일정에 따라 숙박 일정이 정해집니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q57', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 56 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '폭염으로 인한 열사병·탈진·질병 등으로 낮 시간에 휴식이 필요한 순례자는 숙소나 별도의 휴식 공간을 이용할 수 있나요? 또한 폐막 미사 이후에도 필요한 경우 숙소를 이용할 수 있나요?', '본대회 기간 동안 폭염이나 건강 이상으로 낮 시간에 휴식이 필요한 경우, 지구위원회에서 각 지구별로 지정한 거점 본당을 휴식처로 이용하실 수 있습니다. 순례자들은 해당 거점 본당으로 이동하여 휴식을 취하실 수 있습니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q58', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 57 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '패키지 관련하여, 저희 그룹이 숙박과 교통 없이 참가할 수 있나요? 가능하다면 비용은 얼마인가요? 대부분의 패키지에 교통이 포함되어 있는데, 이러한 서비스가 제외된 옵션이 있는지 궁금합니다. 감사합니다.', '모든 패키지에는 교통이 포함되어 있기에 교통 제외는 불가하니 양해 부탁드립니다. 숙박이 제외된 패키지는 있으니 해당 패키지를 이용 부탁드립니다.' FROM qa_item WHERE question_no = 'Q58' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q59', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 58 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '8월 7일 토요일의 식사는 도시락(팩박스)으로 제공되나요, 아니면 철야기도 장소로 가기 전에 카드로 결제해야 하나요?', '패키지별 식사 구성에 따라, 밤샘기도·폐막미사 기간에는 밀박스가 제공됩니다. 밀박스는 8월 7일 중식·석식과 8월 8일 조식·중식 등 총 4끼로 구성됩니다. 밀박스가 포함된 순례자 패키지는 해당 4끼를 선불카드(Prepaid meal card)로 별도 결제하지 않고 밀박스로 제공받습니다. 구체적인 배부 시간·장소 등 현장 운영방안은 추후 안내할 예정입니다.' FROM qa_item WHERE question_no = 'Q59' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q60', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 59 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '음식 알레르기, 글루텐 불내증, 채식 등 특별한 식이 요구가 있는 순례자를 위한 식사 옵션은 어떻게 제공되나요? 도시락과 선불카드(Prepaid meal card) 이용 매장에서 땅콩, 소고기, 해산물, 새우, 채식 알레르기 유발 성분 및 식재료 정보를 확인할 수 있나요? 또한 알레르기 정보는 반드시 앱을 통해서만 등록해야 하나요, 아니면 다른 방법도 제공되나요?', '식사에 대해서는 글루텐프리·비건 등 특수식 제공 여부와 식품정보 표시 방안을 검토하고 있습니다. 선불카드(Prepaid meal card) 이용 매장의 알레르겐·원재료 등 식품정보 제공 여부와 제공 방식도 함께 검토 중입니다. 특수식의 제공 범위와 신청 방법, 변경 가능 기한 등은 세부 운영계획이 확정되는 대로 안내할 예정입니다.' FROM qa_item WHERE question_no = 'Q60' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q61', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 60 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD 기간 중 다치거나 아픈 사람을 위한 특수 이동 지원(장애인/환자 이송)이 제공되나요?', '행사장 주변에 응급차가 상시 대기할 예정이며, 주변 병원과도 연계해서 의료서비스를 제공할 계획입니다.' FROM qa_item WHERE question_no = 'Q61' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q62', s.id, t.id, NULL, 61 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '세이프가딩 정책에 따르면 한국에서 미성년자 기준은 만 18세 7개월 미만인데, 저희 나라에서는 만 18세 미만입니다. 이 경우 보호자 동반 확인서(샤프론 레터)가 없을 것입니다.', '국가별로 미성년자 기준이 다를 수 있으나, 서울 WYD 참가 시에는 '' 미성년자 및 취약 성인 보호 지침'' 에 따른 기준이 적용됩니다. 해당 지침에서는 대한민국 청소년 보호법의 연령 기준을 적용하여, 2009년 1월 1일 또는 그 이후에 출생한 참가자를 미성년자로 분류하고 있습니다. 이는 성인 자격이 요구되는 순례자 그룹 대표 및 부대표, 봉사자, 미성년자 인솔자 등의 기준이 되기도 합니다. 따라서 자국에서 성인으로 인정되는 참가자라도 위 출생일 기준에 해당하면, 부모 또는 법적보호자가 동행하거나 이들로부터 위임 받은 성인 인솔자가 동행해야 합니다. 성인 인솔자는 미성년자 최대 10명당 1명 이상이 필요합니다. 위임받은 성인 인솔자는 해당 미성년자의 부모 또는 법적보호자로부터 서면 위임 동의서를 받아 대회 기간 내내 지참해야 합니다.' FROM qa_item WHERE question_no = 'Q62' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q63', s.id, t.id, NULL, 62 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '대규모그룹(Macrogroup) 안에서 미성년자 등록은 어떻게 진행되나요? 미성년자를 먼저 등록하고 이후에 인솔자를 등록하나요, 아니면 특정 인솔자와 미성년자를 함께 등록하나요?', '등록 2단계에서 그룹의 전체 참가 인원과 미성년자의 수, 성별을 입력하게 됩니다. 대규모그룹(Macrogroup) 내에서도 미성년자와 인솔자의 등록 순서는 정해져 있지 않으며, 특정 인솔자와 미성년자를 연결하여 등록하는 별도의 절차는 없습니다. 다만, 서울 세계청년대회의 " 미성년자 및 취약 성인 보호 지침"에 따라 미성년자 최대 10명당 성인 인솔자 1명 이상이 동행해야 합니다. 위임받은 성인 인솔자는 해당 미성년자의 부모 또는 법적 보호자로부터 서면 위임 동의서를 받아 대회 기간 내내 지참해야 합니다. 또한 미성년자가 홈스테이에 배정되는 경우에는 같은 성별의 미성년자 2명당 같은 성별의 성인 인솔자 1명이 함께 해야 합니다. 따라서 위 보호 지침에 따른 인솔자 수와 성별 구성을 고려하여 미성년자와 인솔자의 등록을 진행해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q63' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q64', s.id, t.id, NULL, 63 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '만 18~19세 청년에게 문제가 생겼을 경우, 한국 법이 적용되나요, 아니면 그 청년의 본국 법이 적용되나요?', '기본적으로 대한민국의 법이 적용되고, 각국 법령에 따라 본국의 법도 중복 적용될 수 있습니다.' FROM qa_item WHERE question_no = 'Q64' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q65', s.id, t.id, NULL, 64 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '미성년 순례자의 참가를 위해 필요한 부모·법정대리인 동의서 및 인솔자(Chaperone) 지정 등 특별한 서류가 있나요? 사용할 수 있는 공식 양식(한국어/영어)을 제공할 예정인가요?', '미성년 순례자의 참가를 위해서는 부모 또는 법적 보호자가 미성년자의 참가에 동의하며, 대회 기간 동안 성인 인솔자에게 미성년자의 보호를 맡긴다는 서면 동의서가 필요합니다. 미성년자의 인솔자는 대한민국 청소년 보호법에 따라 성인 (2008년 12월 31일 당일 또는 이전 출생자)에게 위임되어야 합니다. 미성년자 법적 보호자 동의서 서식은 등록시스템에서 6개 공식 언어로 제공 받을 수 있습니다.' FROM qa_item WHERE question_no = 'Q65' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q66', s.id, t.id, NULL, 65 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '미성년자가 인솔자·부모와 같은 숙소에 머물 수 있는지, 그룹에서 분리되어 별도 숙소에 배정되는지, 인솔자와 함께 머물 수 없는 경우 누가 미성년자를 책임지는지 알고 싶습니다.', '미성년 순례자는 부모 또는 성인 인솔자(부모 또는 법적 보호자의 동의 하에 서면 위임서에 인솔자로 명시된 자)와 동일한 숙소에 함께 배정될 예정입니다. 부모가 아닌 성인 인솔자와 동행할 경우, 동일한 숙소에서 숙박 공간은 물리적으로 분리하여 운영할 계획입니다. 하지만, 미성년자 숙소 운영 방식은 각 국가의 미성년자보호 규정과 현장의 안전 상황에 따라 다양한 방안이 적용될 수 있으며, 모든 경우에 일률적으로 적용되는 단일 정책을 정하기는 어렵다는 점을 양해 부탁드립니다. 조직위원회는 2027 서울 WYD 미성년자보호지침을 제시하는 동시에, 각 국가 주교회의의 미성년자보호지침과 기준을 존중합니다. 다만, 해당 기준에 따라 어떠한 숙소 운영 방식을 선택할 것인지에 대한 결정과 그에 따른 책임은 각 순례자 그룹이 부담하게 됩니다.' FROM qa_item WHERE question_no = 'Q66' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q67', s.id, t.id, NULL, 66 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '스코틀랜드 세이프가딩 규정상 수도자·성직자 리더는 청년들과 같은 숙소에 머물 수 없습니다. 이들을 위한 별도 공간이 마련되나요? 화장실은 어떻게 되나요?', '수도자·성직자 리더를 위한 별도 공간은 준비되어 있지 않습니다. 등록 후 별도로 요청 주시면 반영될 수 있도록 최선을 다하겠습니다. 다만, 숙소의 여건 상 제공이 어려울 수 있는 점 양해 부탁드립니다.' FROM qa_item WHERE question_no = 'Q67' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q68', s.id, t.id, NULL, 67 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '미성년자가 응급 상황으로 병원 진료 또는 입원이 필요한 경우, 그룹 리더가 동행하여 의료 상태 및 치료 정보를 제공받을 수 있나요? 또한 이를 위한 보호자 동의 및 의료정보 공유 관련 사항이 미성년자 등록 양식에 포함되나요?', '현재 미성년자 등록 절차에는 성인 인솔자 또는 그룹 대표의 의료 관련 동의 및 의료정보 공유에 관한 별도 항목을 표기하고 있지 않습니다. 다만, 부모 또는 법적 보호자로부터 서면 위임 동의서를 받은 성인 인솔자는 미성년자에 대한 포괄적인 인솔 권리를 획득하는 것으로 볼 수 있습니다. 현재 검토·수정 중인 "미성년자 및 취약 성인 보호 지침"에 응급 진료 시 보호자 동의와 의료정보 공유에 관한 사항을 포함하는 방안을 고려하고 있으며, 세부 절차는 확정 후 안내드리겠습니다.' FROM qa_item WHERE question_no = 'Q68' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q69', s.id, t.id, NULL, 68 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '부모와 동행하는 미성년자 또는 어린이를 위한 특별 패키지 (가족 단위 특별 패키지) 가 있나요? 이 경우 숙박 배정은 어떻게 진행되나요 ? 또한 만 14세 미만도 부모 중 한 명이 동행하면 참가할 수 있나요 ?', '부모와 동행하는 미성년자 또는 어린이를 위한 별도의 가족 특별 패키지는 마련되어 있지 않습니다. 만 14세 미만의 어린이도 부모 중 한 명 이상 또는 법적 보호자가 위임한 성인 인솔자와 동행하여 참가할 수 있습니다. 다만, 조직위원회에서 제공하는 숙소가 포함된 패키지는 2013년 7월 31일 또는 그 이전에 출생한 참가자만 신청할 수 있습니다. 조직위원회가 제공하는 숙소는 학교·공공시설 등 공동 숙박시설과 홈스테이를 중심으로 운영됩니다. 이러한 숙박 환경과 대규모 순례자 수용 여건을 고려할 때, 만 14세 미만의 자녀와 함께 참가하는 가족은 숙소가 포함되지 않은 패키지로 등록하고, 가족에게 적합한 숙소를 직접 마련해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q69' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q70', s.id, t.id, NULL, 69 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '개별 등록이 없는 그룹 등록 방식에서 각 순례자의 세이프가딩 정책 및 행동강령(Code of Conduct)에 대한 동의·서명은 어떻게 이루어지나요? 또한 등록 시스템 오픈 전에 관련 가이드라인을 사전 제공하고, 순례자를 위한 별도의 교육도 제공할 예정인가요?', '등록시스템에서는 참가 유형에 따라 순례자 그룹 대표, 성직자 (사제·부제), 주교, 봉사자, 가톨릭문화박람회 참가자, 젊은이 축제 참가자 및 언론인 등이 세이프가딩 정책과 행동 강령(Code of Conduct) 에 동의·서명하도록 되어 있습니다. 개별 순례자도 순례자앱을 통해 해당 정책과 행동강령에 동의·서명해야 합니다. 현재 세이프가딩 지침서와 행동강령은 검토·수정 중이며, 최종본은 2027년 초 등록시스템, 공식 홈페이지 및 각국 주교회의 등을 통해 공유할 예정입니다. 또한 순례자가 세이프가딩 정책과 행동강령을 이해하고 준수할 수 있도록 교육 자료도 함께 제공할 예정입니다.' FROM qa_item WHERE question_no = 'Q70' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q71', s.id, t.id, NULL, 70 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '장애인 순례자는 장애 유형이나 지원 필요에 따라 별도 숙소가 배정되는지, 또한 한국 도착부터 출국까지 전담 인력의 지원을 받을 수 있는지 궁금합니다.', '장애인 순례자도 소속 교구와 함께 동행하는 것이 원칙이지만, 원한다면 별도 숙소에 배정할 수 있습니다. 또한 한국 도착부터 출국까지 그룹 내 동행인이 있으면 좋겠지만, 없다면 봉사자 배정도 고려하고 있습니다.' FROM qa_item WHERE question_no = 'Q71' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q72', s.id, t.id, NULL, 71 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '장애인 순례자는 소속 교구/주교회의 대표단등 소속 그룹과 함께 숙박하고 행사에 참여하면서 필요한 접근성·이동 지원을 받을 수 있나요?', '장애인 순례자는 소속 교구와 주교회의 대표단 등 소속 그룹과 함께 숙박하면서 필요한 접근성 이동 지원을 받을 수 있을 것입니다. 구체적인 지원 내용은 추후 앱이나 홈페이지를 통해 안내해 드리겠습니다.' FROM qa_item WHERE question_no = 'Q72' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q73', s.id, t.id, NULL, 72 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅱ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '장애인 순례자의 등록 절차는 어떻게 되나요? 보호자 또는 동행인의 등록이 필수인지, 필요한 경우 장애인 순례자와 동행인을 어떻게 함께 등록하는지도 안내 부탁드립니다.', '등록시에 장애인 순례자와 동행하는지의 여부를 묻는 체크 리스트 항목이 있습니다. 해당 한다면 그 곳에 체크해 주십시오. 동행인 등록이 필수는 아니며, 동행인이 있는 경우에는 동행인도 순례자로 등록 하시고 비고란에 동행인 이름과 연락처를 기입해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q73' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q74', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 73 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자 키트와 카드 등은 어디에서 수령하나요? 숙박 포함 그룹과 숙박 미포함 그룹의 체크인 및 물품 수령 장소는 각각 어디인가요?', '숙박이 포함된 패키지로 등록한 그룹은 배정된 본당에서 체크인하고 순례자 키트와 카드 등을 수령하게 됩니다. 해당 물품은 조직위원회에서 각 본당으로 사전에 배송할 예정입니다. 숙박이 포함되지 않은 패키지로 등록한 그룹은 순례자센터에서 체크인하고 순례자 키트와 카드 등을 수령하게 됩니다. 현장 등록 참가자도 순례자센터에서 등록 절차를 마친 후 해당 물품을 수령하실 수 있습니다.' FROM qa_item WHERE question_no = 'Q74' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q75', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 74 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자 키트에는 무엇이 들어있나요?', '백팩(가방), T-shirts, 모자, 물통, 부채(접이식), 스포츠타올, 묵주(팔찌)가 포함될 예정이나, 일부 아이템은 바뀔 가능성 있습니다.' FROM qa_item WHERE question_no = 'Q75' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q76', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 75 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '스마트폰이 없는 순례자는 체크인 및 행사 참여에 필요한 정보와 서비스에 어떻게 접근하며, 식사카드 등 필요한 카드와 물품은 어떤 방식으로 제공받나요?', '리더 그룹이 카드 활성 및 추가적인 정보 제공을 해야 합니다. 체크인 시 그룹리더가 대표해서 선불카드를 포함한 KIT를 제공받고 구성원들에게 배분합니다.' FROM qa_item WHERE question_no = 'Q76' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q77', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 76 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '사제와 부제는 소속 그룹과 함께 체크인하나요, 아니면 별도의 지정 장소에서 체크인해야 하나요? 그룹 리더가 사제·부제를 대신하여 신분 확인 및 영대 등 성직자용 물품을 수령할 수 있는지, 또는 본인이 직접 방문해야 하는지 궁금합니다.', '숙박이 포함된 패키지로 등록한 사제와 부제는 배정된 본당에서 소속 그룹과 함께 체크인할 수 있습니다. 다만, 체크인 담당자가 사제·부제의 신분을 직접 확인한 후 크리덴셜과 키트를 지급하므로, 그룹 리더가 신분 확인이나 해당 물품 수령을 대신할 수는 없습니다. 숙박이 포함되지 않은 패키지로 등록한 사제와 부제는 순례자센터 내 사제·부제 전용 체크인 장소를 직접 방문하여 신분 확인과 물품 수령을 진행해야 합니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q78', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 77 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '숙박 미포함 그룹의 경우 그룹 리더가 전체 순례자를 동반하지 않고 대표로 순례자센터에서 체크인 및 물품 수령을 할 수 있나요?', '가능합니다. 숙박이 포함되지 않은 패키지로 등록한 그룹은 전체 참가자가 동행하지 않아도 그룹 리더가 대표로 순례자센터를 방문하여 그룹 체크인과 물품 수령을 진행할 수 있습니다. 다만, 그룹에 소속된 사제와 부제는 순례자센터 내 사제·부제 전용 체크인 장소를 직접 방문하여 별도의 체크인 절차를 진행해야 합니다.' FROM qa_item WHERE question_no = 'Q78' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q79', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 78 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자센터는 하루 중 몇 시부터 몇 시까지 운영되나요?', '현장등록과 비숙박 포함 패키지를 신청한 그룹의 체크인이 진행될 순례자센터는 단기 봉사자 체크인이 시작되는 7월 25일부터 8월 8일까지 운영 예정입니다. 보다 구체적인 운영 계획은 추후 공지 드리도록 하겠습니다.' FROM qa_item WHERE question_no = 'Q79' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q80', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 79 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자 앱 사용 등 원활한 인터넷 이용을 위해 WYD 기간 동안 숙소와 주요 행사장 등에 공공 Wi-Fi가 제공되나요? 대규모 순례자가 동시에 접속할 경우에도 안정적으로 이용할 수 있는 통신 환경이 마련되나요?', '서울시내에는 많은 공공 와이파이가 설치되어 있습니다. 조직위원회는 순례자들의 편의와 안전을 위해 서울시 및 관련 기업, 기관들과 다양한 분야에서 협력 중입니다.' FROM qa_item WHERE question_no = 'Q80' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q81', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 80 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교황청이 승인한 순례길의 운영 방식과 참여 방법, 순례 확인서 또는 증명서 발급 절차도 안내받을 수 있나요?', '교황청이 승인한 순례길은 별도의 신청 없이 언제든지 자유롭게 방문하여 걸으실 수 있습니다. 순례길은 총 24개소, 3개 코스(1코스 말씀의 길 / 2코스 생명의 길 / 3코스 일치의 길)로 구성되어 있습니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q82', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 81 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '그룹 리더와 하위그룹 리더도 같은 앱 안에서 자신의 순례자 기능과 리더 기능을 함께 사용할 수 있는지 궁금합니다. 즉, 본인 화면과 리더용 화면을 서로 전환할 수 있는지에 관한 물음입니다.', '불가능합니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q83', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 82 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '각 순례자는 개인 계정과 접속 정보를 받아 직접 앱을 활성화하나요?', '웹회원은 개인별로 자유롭게 가입합니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q84', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 83 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '하나의 계정에 이메일 하나를 사용할 경우, 그룹 내에서 해당 이메일과 비밀번호를 공유해서 로그인해야 하나요, 아니면 앱상으로는 같은 그룹에 여러 항목으로 들어가더라도 각 참가자가 자신만의 계정으로 로그인하나요?', '계정은 개인 정보이기에 개별적으로 가입해야 합니다. 그룹코드 인증과는 별개입니다.' FROM qa_item WHERE question_no = 'Q84' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q85', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 84 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '앱을 사용하려면 인터넷에 연결되어 있어야 하나요? 그렇다면 와이파이가 제공되나요, 아니면 순례자가 심카드나 이심(eSIM)을 구매해야 하나요?', '순례자는 공공 와이파이 및 개인의 셀룰러 데이터를 이용하여 앱을 사용할 수 있습니다. 다만 오프라인 상태에서도 최소기능은 유지될수 있도록 제작되었습니다(ex. 행사안내 등) 순례자는 본인의 심카드나 이심(eSIM)을 직접 구매하여 사용해야 합니다.' FROM qa_item WHERE question_no = 'Q85' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q86', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 85 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자앱에는 다국어 번역, 문의용 챗봇 등의 기능이 제공되나요? 예를 들어 텍스트를 사진으로 찍어 번역하거나, 대화를 음성으로 번역하는 기능이 있나요?', '순례자앱에서는 6개 국어가 제공됩니다. 번역 및 통역 관련 별도 기능은 제공되지 않습니다.' FROM qa_item WHERE question_no = 'Q86' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q87', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 86 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자앱을 통해 주변 식당의 위치·수용 가능 인원 등 순례자에게 필요한 현지 정보를 제공하거나 실시간으로 안내받을 수 있나요? 순례지 주변 식당을 이용할 시 한꺼번에 많은 팀이 몰려서 식당을 찾아 해매다가 식사 시간을 놓치거나 예상 밖의 메뉴로 식사를 해결 못 할 경우도 있을것 같습니다.', '순례자앱을 통해 모든 식당의 현재 정보를 제공해드리지는 않습니다.' FROM qa_item WHERE question_no = 'Q87' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q88', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 87 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자앱은 언제부터 다운로드하여 사용할 수 있으며, iOS와 Android 모두 지원하나요? 또한 인터넷 연결이 원활하지 않은 상황에서도 앱의 주요 기능을 오프라인으로 사용할 수 있나요?', '현재 서비스 제공중에 있습니다. 온라인에서 기본적인 정보를 일정 시간마다 업데이트해서 오프라인에서도 사용 가능하지만, 신규 정보 추출은 온라인상에서만 가능합니다.' FROM qa_item WHERE question_no = 'Q88' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q89', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 88 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '주요 행사의 실시간 통역은 순례자앱에서도 이용할 수 있나요, 아니면 라디오 주파수를 통해서만 가능한가요?', '순례자앱에서는 실시간 통역 기능을 제공하지 않습니다.' FROM qa_item WHERE question_no = 'Q89' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q90', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 89 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '그룹 리더와 순례자가 각각 입력해야 하는 정보는 무엇이며, 여권·티셔츠 사이즈·알레르기 등의 정보는 어떻게 등록하나요? 그룹 리더용 대시보드의 기능도 안내해 주시기 바랍니다.', '사전정보 입력은 그룹 리더만 등록 가능합니다. 순례자는 사전정보 입력이 불가합니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q91', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 90 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '앱에는 어떤 개인정보가 언제 입력되며, 티셔츠 사이즈·알레르기 등의 정보는 순례자가 직접 입력하나요, 아니면 그룹 리더가 관리하나요? 이러한 정보를 웹사이트에서도 입력·관리할 수 있는지와 개인정보 보호 및 앱 보안 대책도 안내 부탁드립니다.', '기본적으로 웹회원은 본인 이메일 주소로 인증번호가 발송됩니다. 사전 입력 정보는 그룹 리더만 입력합니다. 개인정보에 해당되는 영역은 기본 웹회원에만 해당 되며 법적 검토된 내용으로 회원가입 시 약관 제공 및 동의를 받습니다.' FROM qa_item WHERE question_no = 'Q91' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q92', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 91 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '참가자들이 순례자 앱을 사전에 익할 수 있도록 공식 사이트에 단계별 사용 가이드나 사전 체험 환경을 제공할 예정인가요?', '현재 앱은 서비스 진행중이며, 앱관련 사전 가이드가 제공될 예정입니다.' FROM qa_item WHERE question_no = 'Q92' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q93', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 92 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD 순례자 교통카드를 Apple Pay, Google Pay, Samsung Pay 등 모바일 지갑에 등록하여 사용할 수 있나요?', '순례자 카드는 교통카드와 결제 카드가 통합된 실물카드를 발행해드립니다. 해당 실물카드는 NFC와의 연동은 지원하지 않습니다.' FROM qa_item WHERE question_no = 'Q93' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q94', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 93 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD 이후, 선불카드(Prepaid meal card)는 카드에 예를 들어 100달러 정도의 잔액이 남아 있다면 환불받을 수 있나요? 환불이 가능하다면 원화로 받나요, 달러로 받나요? 아니면 최소한 연대기금(Solidarity Fund)에 기부할 수 있게 해줄 수 있나요?', '조직위원회에서 매일 충전하는 식사비는 당일 식사비를 모두 사용하지 않은 경우, 잔액이 이월되며 등록한 패키지의 종료일까지 사용할 수 있습니다. 대회 종료 이후 미사용 잔액에 대해서는 환불되지 않습니다. 미사용된 잔액은 참가 분담금의 일환으로 기부하는 방안을 논의 중입니다. 추후 자세한 안내 드리겠습니다.' FROM qa_item WHERE question_no = 'Q94' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q95', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 94 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '선불카드(Prepaid meal card)는 실물 카드인가요, 디지털인가요? 로마 희년(Jubilee) 행사 당시 앱에 큰 문제가 있어 일부 그룹은 모든 식사를 받지 못했습니다.', '선불카드(Prepaid meal card)는 실물 카드입니다. 순례자앱에서는 결제 기능을 제공하지 않으며, 사용 내역과 잔액을 확인할 수 있습니다.' FROM qa_item WHERE question_no = 'Q95' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q96', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 95 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD 기간의 식사는 선불카드(Prepaid meal card)를 이용해 식당·편의점 등에서 자유롭게 선택하는 방식인가요, 아니면 별도의 식사 텐트나 도시락도 제공되나요? 이용 가능한 식당 및 편의점에서는 다양한 문화권의 음식점도 포함되나요?', '조식은 숙소에서 일괄 제공하는 방식으로 운영하며, 중식 및 석식은 선불카드(Prepaid meal card)를 이용하여 지정된 식당에서 자유롭게 이용할 수 있도록 운영할 예정입니다. 이용가능한 식당, 메뉴 및 식사카드 운영방식 등은 구체적인 사항은 현재 협의 중입니다.' FROM qa_item WHERE question_no = 'Q96' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q97', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 96 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '선불카드(Prepaid meal card)를 사용하려면 휴대폰에 NFC 기능이 필요한가요?', '아니오. 체크인시 수령받는 실물카드로 활성 및 폰에 연동해서 사용가능합니다. NFC 기능을 필요하지 않습니다.' FROM qa_item WHERE question_no = 'Q97' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q98', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 97 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '순례자 카드를 분실했을 때 제2리더(second leader)만 새 카드를 발급/요청할 수 있나요, 아니면 제1리더도 가능한가요?', '앱관련 모든 권한은 제2리더만 가능합니다. 정책적으로 하위그룹(Subgroup)리더, 제1리더는 중복이 가능하기에 유니크한 리더 계정은 제2리더만 해당되어 이런 결정을 내렸습니다.' FROM qa_item WHERE question_no = 'Q98' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q99', s.id, t.id, NULL, 98 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD 기간 중 대륙별·지역별·국가별 모임을 조율하는 조직위원회의 전담 창구나 담당자가 있으며, 이러한 모임을 위한 장소가 제공되나요? 아니면 주최 단체가 직접 장소를 마련해야 하나요?', '대륙별 또는 국가별 모임 제안은 국제부(international@wydseoul.org)로 문의해 주시기 바랍니다. 행사 운영 및 실무와 관련된 자세한 안내를 받으실 수 있습니다.' FROM qa_item WHERE question_no = 'Q99' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q100', s.id, t.id, NULL, 99 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD에 직접 참가하지 못하는 국가와 청년들이 자국 교구나 본당에서 자체 행사 및 철야기도를 통해 함께 참여할 수 있도록, 조직위원회에서 공식 프로그램과 기도 자료를 제공할 예정인가요?', '조직위원회는 여러가지 이유로 현장에서 함께 할 수 없는 순례자들을 위해 다양한 방법을 기획, 준비하고 있습니다. 참여 형식과 방법이 확정되는 대로 공지할 예정입니다.' FROM qa_item WHERE question_no = 'Q100' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q101', s.id, t.id, NULL, 100 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '저희는 숙소 미포함 패키지를 선택할 예정이며, 신부님들도 함께 계십니다. WYD에서 미사가 계획되지 않은 날, 저희 그룹을 위해 신부님이 미사를 집전할 수 있는 인근 본당을 어떻게 마련할 수 있나요?', '서울 시내 대부분의 본당은 숙소 포함 패키지를 이용하는 그룹이 배정될 예정입니다. 이에, 배정된 그룹이 우선적으로 해당 본당을 사용하게 됩니다. 배정된 그룹이 사용하지 않는 시간대로 이용을 요청하셔야 하니 양해부탁드립니다.' FROM qa_item WHERE question_no = 'Q101' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q102', s.id, t.id, NULL, 101 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '3' WHERE s.code = 'Ⅲ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD를 준비하는 순례자들을 위해 이단·사이비 활동 등에 대한 안전·인식 제고 자료가 제공되나요?', '현재 한국천주교주교회의 유사종교대책위원회에서 안내 자료를 작성하고 있으며, 초안 검토 중입니다. 검토 후 공식언어로 번역하여 배포할 예정입니다.' FROM qa_item WHERE question_no = 'Q102' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q103', s.id, t.id, NULL, 102 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '입국날짜를 서울 도착일이 아니라 교구대회를 위한 입국 비자를 위한 날짜라고 밝혀야 할 것 같네요
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q104', s.id, t.id, NULL, 103 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '알러지 정보는 교구대회 관계자에게 공유 되나요? 교구대회 참가비와 공헌금 등록은 별도로 진행 하고 별도로 결재 해야 하겠지만 링크는 제공하나요? 완전히 별개로 모두 다시 입력하나요', '교구대회를 신청하면서 현재는 규모만 등록한 상태이고, 이후 교구에서 명단을 제출할 때 세부정보를 요청할 예정입니다. 이때 알러지 및 기타 특이사항을 수집하게 됩니다. 교구대회 기부금은 참가 교구로 납부하게 되고 계좌이체로 진행될 예정입니다.' FROM qa_item WHERE question_no = 'Q104' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q105', s.id, t.id, NULL, 104 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교구대회를 진행하는 교구에서 서울로 가는 교통비는 교구에서 지원받을 수 있나요?', '교구대회의 운영은 교구마다 다릅니다. 교구대회 후 본대회 이동에 대해서는 참가를 희망하는 교구에 직접 문의하시길 바랍니다.' FROM qa_item WHERE question_no = 'Q105' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q106', s.id, t.id, NULL, 105 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교구대회 참가 시 공항에서 주최 교구까지, 서울에서 주최 교구까지, 그리고 교구대회 종료 후 서울 숙소까지의 교통편은 주최 측에서 제공하거나 패키지에 포함되나요, 아니면 각 대표단·그룹이 직접 준비해야 하나요?', '교구대회의 운영은 교구마다 다릅니다. 공항에서 교구대회 교구까지, 교구대회 교구에서 본대회까지의 교통편은 참가를 희망하는 교구에 직접 문의하시길 바랍니다.' FROM qa_item WHERE question_no = 'Q106' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q107', s.id, t.id, NULL, 106 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교구대회 등록은 언제 시작하나요?', '교구대회의 등록은 이미 시작하였습니다. 방문, 전화, 이메일, 교구대회 홈페이지(https://wyd2027did.org)를 통해 신청이 가능합니다. 다만 교구대회를 위해 준비된 인원이 채워진 교구로는 신청이 어렵습니다.' FROM qa_item WHERE question_no = 'Q107' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q108', s.id, t.id, NULL, 107 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교구대회 기간도 보험 적용 대상인가요?', '교구대회를 운영하는 교구는 행사보험을 준비하고 있습니다. 하지만 개인 여행자 보험은 순례자가 준비하시길 바랍니다.' FROM qa_item WHERE question_no = 'Q108' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q109', s.id, t.id, NULL, 108 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '2027년 7월 29일 이전에 교구대회를 위해 도착하는 분들을 위한 숙박 해결책이 있나요?', '교구대회의 운영은 교구마다 다릅니다. 조기 도착에 따른 숙박문제는 참가를 희망하는 교구에 직접 문의하시길 바랍니다.' FROM qa_item WHERE question_no = 'Q109' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q110', s.id, t.id, NULL, 109 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '미성년자가 교구대회에 참가할 때 홈스테이를 하게 되나요?', '현재 대부분의 교구는 홈스테이를 기본으로 준비하고 있습니다. 미성년자가 교구대회에 참가할 때에는 보호자 동반하에서만 홈스테이를 하게 됩니다. 미성년자 수에 맞추어 충분한 보호자를 확보하시길 바랍니다. 홈스테이가 아닌 별도의 숙박에 대해서는 참가를 희망하는 교구에 직접 문의하시길 바랍니다.' FROM qa_item WHERE question_no = 'Q110' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q111', s.id, t.id, NULL, 110 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '많은 교구가 이미 정원이 찼나 보네요. 그렇다면 우리가 교구를 찾기에 너무 늦은 건 아닐까요?', '10월 7일 현재 순례자들의 교구대회 참가를 위해 준비한 인원의 55%가 신청되었습니다. 아직은 여유가 있는 상황이고, 한국 교회가 교구대회를 위해 준비한 인원에 비해 신청이 초과하더라도 이를 수용할 여유가 있습니다. 교구대회 참가를 희망하는 모든 순례자를 환영합니다. 걱정하지 마시고 신청하시기 바랍니다.' FROM qa_item WHERE question_no = 'Q111' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q112', s.id, t.id, NULL, 111 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교구대회 등록은 언제부터 유효한가요? 일부 교구에서는 이미 연락을 주셨지만, 실제 WYD 등록은 10월이 되어야 시작됩니다. 교구대회 등록만으로도 이미 유효한 건가요, 아니면 WYD 등록을 해야만 유효해지는 건가요?', '교구대회의 등록은 본대회와 별개로 진행됩니다. 그리고 교구대회의 등록은 이미 시작되었고 다음과 같은 3단계로 진행됩니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q113', s.id, t.id, NULL, 112 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '또한 교구대회에서 WYD로 이동하는 날짜는 8월 2일인가요, 3일인가요?', '교구대회는 2027년 7월 29일부터 8월 2일까지 4박 5일의 일정으로 진행됩니다. 8월 2일 일정을 마치고 당일 본대회로 이동하게 됩니다.' FROM qa_item WHERE question_no = 'Q113' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q114', s.id, t.id, NULL, 113 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '국제 운동, 공동체 및 평신도 단체들이 각자의 고유한 카리스마를 발휘하며 DID 프로그램에 어떻게 통합되고 있나요?', '교구대회의 운영방향은 순례자들의 지역 교회 체험입니다. 고유의 카리스마와 교구대회 프로그램과의 통합은 참가를 희망하는 교구에 직접 문의하시길 바랍니다.' FROM qa_item WHERE question_no = 'Q114' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q115', s.id, t.id, NULL, 114 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '1' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '비용과 결제 얼마인가요? 무료인가요, 아니면 별도 요금이 있나요? 등록과 동시에 결제하나요, 아니면 교구에 직접 결제하나요?', '교구대회 순례자 기부금은 모든 교구 동일하게 $100입니다. 대부분의 교구는 홈스테이와 아침식사, 행사보험, 기념품을 제공합니다. 아침식사 이외 식사나 교통편 및 기타 비용은 참가를 희망하는 교구에 직접 문의하시길 바랍니다.' FROM qa_item WHERE question_no = 'Q115' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q116', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 115 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '월드컵경기장과 평화공원 관련 상황이 매우 우려됩니다. 스타디움 수용 인원이 6만 명이라 사람들을 공평하게 순환시킬 기회가 없을 것입니다. 많은 사람에게 매우 불공평하게 느껴질 것이며, 이 계획은 여전히 많은 청년을 배제하고 거부하는 결과가 될 것입니다. 평화공원/월드컵경기장에서 열리는 세 행사 각각에서 실내외 좌석은 어떤 기준으로 그룹을 선정하나요? 추첨인가요? 이것이 배제적으로 보이지 않게 하려면 어떻게 해야 할까요? 마치 ''가진 자와 못 가진 자''를 나누는 상황처럼 보입니다. 청년들에게는 배타적이지 않은 무언가가 필요합니다. 교회가 그들을 또다시 거부하는 조직이 되지 않았으면 합니다.', '행사를 담당하는 입장에서 질문자의 우려스러운 마음을 충분히 이해합니다. 그러한 걱정이 불공평함이 되지 않도록 소통의 원칙과 기준을 세우고 배정할 것입니다. 또한 경기장 내부에 앉는것이 특권이 되지 않고 평화의 공원에 앉는것이 소외가 되지 않도록 여러 배려와 소통의 장치들을 마련할 것입니다.' FROM qa_item WHERE question_no = 'Q116' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q117', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 116 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '십자가의 길 구분에 중미와 카리브해 지역이 보이지 않습니다. 고려될 예정인가요?', '십자가의 길과 본대회의 모든 행사의 대륙구분은 교황청에서 나누는 대륙을 기준으로 구분합니다.' FROM qa_item WHERE question_no = 'Q117' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q118', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 117 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '개회 미사, 교황 환영식, 십자가의 길 등 주요 행사에서 스타디움 내부와 외부 구역은 어떤 기준으로 그룹과 순례자에게 배정되나요? 주교회의 대표단 등에 우선권이 있는지, 사전 지정 또는 추첨 방식인지 궁금합니다. 또한 스타디움 수용 인원을 초과하는 순례자들도 현장에서 행사와 미사에 의미 있게 참여할 수 있도록 어떤 방안이 마련되나요?', '경기장내 좌석은 사전 배정을 하겠지만 일부 성직자들에게 우선권을 주지 않을 것입니다. 청년대회는 소외된 청년들과 장애인 그리고 각국의 청년 대표들을 우선 배려해야 합니다. 공원의 순례자들을 위한 다양한 장치와 배려 방안이 논의되고 있습니다. 경기장이 특권이 되지 않고 공원에 앉아도 아쉽지 않도록 하는 다양한 배려와 소통의 방안들을 준비중입니다.' FROM qa_item WHERE question_no = 'Q118' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q119', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'a'), 118 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '행사가 스타디움 안에서 폐쇄적으로 진행되어 고립된 느낌을 줄까 걱정됩니다. 교황님께서 가까이 다가가는 목자가 되고자 하시더라도, 이것이 모두를 위한 대회라는 느낌을 갖기 어려울 것 같습니다.', '대회가 경기장이라는 공간에 고립되어 진행되지 않도록 다양한 방법을 고민 중입니다. 경기장과 서울을 넘어 지구 반대편에 있는 청년들은 물론이고, 경기장 외부의 청년들과 소통하는 다양한 방법을 준비중입니다.' FROM qa_item WHERE question_no = 'Q119' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q120', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 119 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '현재 교통편이 저희를 어디에 내려줄지, 그리고 그곳에서 폐막 미사 장소까지 청년들이 대략 얼마나 걸어야 하는지에 대해 명확한 정보가 있나요?', '현재 운영계획 작성 중이며, 대회 직전 순례자를 위한 수송/교통가이드 배포 예정입니다.' FROM qa_item WHERE question_no = 'Q120' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q121', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 120 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '폐막미사 장소에 관한 기밀 정보에 대해 답변 부탁드립니다. 이 정보를 물어볼 주교님들과 지도자분들께는 공유할 수 없다는 말씀이신가요? 내부적으로 공유하는 것은 괜찮은가요? 아니면 이 정보가 이 방 안에만 머물러야 한다는 말씀이신가요?', '폐막미사 장소에 대한 정보는 주교회의와 교구 차원의 내부 공유가 가능합니다. 하지만 공식적인 발표가 나기 전에 공적인 매체(방송, 인터넷, 유튜브, 신문기사, 개인SNS 등)으로는 공유해서는 안됩니다. 발표가 되기 전까지 기도하는 마음으로 기다려 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q121' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q122', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 121 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '폐막미사 장소에 대해 여쭤보겠습니다. A1과 A3 구역에 신부님들을 배치해 주실 수 있을까요? 그래야 청소년들도 A2 구역, 즉 무대 바로 앞쪽에 자리를 잡을 수 있을 것 같습니다.', '무대 전면의 구역들은 특별히 관리될것입니다. 사제석은 별도의 전면구역에 배정계획중이고 대표청년들, 소외계층의 청년들과 특수참가자들은 별도로 관리되어 무대 앞자리에 배석할 것입니다. 구체적인 좌석배치는 순례자 등록 마감이 되어야 확정됩니다.' FROM qa_item WHERE question_no = 'Q122' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q123', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 122 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '개막 미사와 폐막 미사에 가져갈 수 있는 물품과 가져갈 수 없는 물품에 대한 목록이 미리 공개될 예정인가요? 예를 들어, 폐막 미사 때 텐트를 설치해도 되나요?', '반입가능 물품은 미리 공지될 것이고 상식적으로 하룻밤 비박에 필요한 물품 정도에 한해 가능합니다. 텐트설치는 불가합니다.' FROM qa_item WHERE question_no = 'Q123' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q124', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 123 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '서울 공항에서 열리는 마지막 날 행사 때, 순례자들이 지정된 구역으로 이동하도록 안내해 줄 자원봉사자들이 배치될 예정인가요? 지난번 행사에서는 일부 순례자들이 지정된 구역을 따르지 않고 무대 근처 자리를 차지하려는 경향이 있었기 때문입니다.', '조직위는 대규모 인파가 몰릴 것으로 예상되는 모든 행사에 있어 안전을 최우선으로 고려하여 준비하고 있습니다. 순례자들의 안전을 위해 봉사자 배치를 포함한 많은 방법을 준비하고 실행하겠습니다.' FROM qa_item WHERE question_no = 'Q124' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q125', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 124 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '밤샘기도와 미사에 참석하기 위해 서울 공항까지 어떻게 가면 될까요? 대중교통을 이용해서 갈 수 있을까요?', '지하철과 도보로 이동합니다. 자세한 내용은 대회 직전 순례자를 위한
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q126', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 125 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
