INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q127', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 126 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD 기간 중 예상되는 폭염과 폭우에 대비하여 철야기도 및 폐막 미사 등 야외 행사에서 순례자를 보호하기 위한 대책은 무엇인가요? 그늘막, 식수, 휴식 공간 등은 LOC에서 제공하는지, 모자·양산 등 참가자가 개별적으로 준비해야 할 사항도 안내해 주실 수 있나요?', '행사장 내부에 폭염과 폭우에 대비할 수 있는 대기소나 천막을 설치할 예정이나 모든 사람을 수용하기 어렵기 때문에 각자 모자와 양산을 개별적으로 지참해야 하며 등록이 오픈되면 이를 다시 한 번 안내할 예정입니다.' FROM qa_item WHERE question_no = 'Q127' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q128', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 127 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '철야기도 장소에 예상보다 많은 순례자가 몰려 수용 인원을 초과하거나 혼잡이 발생할 경우, 입장하지 못하는 순례자가 없도록 어떤 입장 관리 및 대체 참여 방안을 마련할 예정인가요? 리스본에서는 일부 순례자가 혼잡으로 인해 철야기도 장소에 들어가지 못했습니다.', '그룹별로 순차이동 가이드를 제공하여 최대한 많은 순례자가 폐막미사에 올 수 있도록 준비중입니다.' FROM qa_item WHERE question_no = 'Q128' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q129', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'b'), 128 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '주요 미사에서 사제의 공동집전과 부제의 전례 참여는 어떻게 운영되나요? 별도의 사전 등록이나 자격 확인이 필요한지, 장백의(Alb)와 영대(Stole) 등 전례복은 개인이 준비해야 하는지도 안내 부탁드립니다.', '개막미사 사제석은 무대 뒷 좌석을 전용좌석으로 고려중입니다. 폐막미사에는 보다 청년들을 제단에 가까이 배려하고자 청년들 좌-우측 맨 끝자리로 사제석을 고려중입니다. 기념 장백의와 영대는 당일 현장에서 무료로 배부합니다.' FROM qa_item WHERE question_no = 'Q129' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q130', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 129 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', 'WYD에서 국제 청년 단체와 외부 주최자가 일반 행사, 워크숍 또는 부대행사를 제안하고 참여·협력할 수 있는 기회와 절차는 어떻게 되나요? 젊은이 축제에 참가하려는 단체는 무엇을 준비해야 하며, 공간·부스의 신청 및 배정 절차와 참가 비용은 어떻게 되나요?', '젊은이 축제에 참가하려는 단체는 등록시스템을 통해서 자신들이 하고자 하는 프로젝트를 신청할 수 있습니다. 공연, 강연, 전시, 기도와 찬양, 워크샵 등 다양한 장르의 프로젝트가 가능하고, 참가비는 무료입니다. 모든 나라에서 참여 가능합니다. 참가팀의 최종 선정은 교황청과 조직위가 하고, 장소는 조직위가 배정 및 제공합니다.' FROM qa_item WHERE question_no = 'Q130' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q131', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 130 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '다른 나라의 청년들은 그들의 젊은이 축제를 어떻게 공연하나요? 등록이 필요한가요? 행사장이 배정되나요? 참가비를 내야 하나요!', '젊은이 축제와 성소박람회는 본대회 기간 동안만 본대회 개최교구에서 운영됩니다. 참가를 원하는 그룹이나 단체는 등록시스템을 통하여 신청할 수 있습니다. 젊은이 축제는 참가비가 없으며, 성소박람회는 부스 1개일 때 700 미국달러, 부스 2개일 때 1,300 미국달러의 부스 비용이 필요합니다. 젊은이 축제의 경우, 프로젝트를 운영하는 팀이 원하는 대로 언어를 결정할 수 있습니다. 대부분 영어를 포함합니다.' FROM qa_item WHERE question_no = 'Q131' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q132', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'c'), 131 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '젊은이 축제와 성소 박람회에 참가하는 절차는 어떤 웹사이트나 홈페이지에서 확인할 수 있나요? 어떻게 알 수 있나요? 이 경험을 더욱 풍요롭게 만들기 위해 우리 각국에서 해당 정보를 널리 알릴 수 있을까요? WYD의 City of Joy, 성소 박람회 및 젊은이 축제는 언제, 어디에서, 어떤 형태로 운영되며, 여러 교구에 분산하여 개최되는지와 언어권별 프로그램이 마련되는지 궁금합니다.', '젊은이 축제와 성소박람회는 등록시스템을 통하여 신청할 수 있습니다. 등록시스템은 10월말경 오픈 예정이며, 공식 홈페이지(https://wydseoul.org/)를 통하여 접근할 수 있습니다. 이 경험을 더욱 풍요롭게 하기 위하여 공식 홈페이지를 널리 홍보해주시기를 부탁드립니다.' FROM qa_item WHERE question_no = 'Q132' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q133', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 132 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '‘화해의 공원’ 기간 동안 사제들은 고해성사를 듣기 위해 어떻게 등록하나요?', '사제들은 등록시스템에서 순례자 그룹 등록 시에 함께 등록합니다. 순례자 그룹 등록은 그룹 대표가 하게 되어있으므로 ''화해의 공원''에서 고해성사를 듣고자 하는 사제들은 본인이 가능한 날짜와 시간을 대표에게 알리면 됩니다. 그룹없이 홀로 순례하는 사제는 1인그룹으로 등록가능합니다.' FROM qa_item WHERE question_no = 'Q133' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q134', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 133 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '성소 박람회의 ‘부스’란 무엇을 의미하나요?', '성소박람회(가톨릭문화박람회)에서 ''부스''란 박람회에 참가하는 각 수도회 또는 사도직/신심 단체에게 주어지는 3m X 3m 짜리의 텐트 또는 스탠드로 만들어진 공간을 의미합니다. 한 수도회 당 최대 2개까지 신청할 수 있습니다.' FROM qa_item WHERE question_no = 'Q134' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q135', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 134 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '성소 박람회의 내용은 무엇인가요? 참가비는 구체적으로 어떤 용도로 사용되나요?', '성소박람회는 참가하는 각 수도회 또는 단체의 카리스마와 영성을 순례자들과 나눔으로써 순례자들로 하여금 자신의 부르심을 식별하도록 도와주는 행사입니다. 참가비용은 행사장 대여와 부스 설치를 위하여 사용됩니다.' FROM qa_item WHERE question_no = 'Q135' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q136', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 135 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '고해성사에 참여하는 사제들의 선정 기준은 무엇입니까? 선별된 사제들만 참여할 수 있는 것입니까, 아니면 누구나 참여할 수 있습니까? 사제들은 등록 시에 참여 여부를 표시해야 합니까?', '사제라면 누구나 참여할 수 있으나 신분 검증을 위해 등록시스템에 등록되어야 합니다.' FROM qa_item WHERE question_no = 'Q136' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q137', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'd'), 136 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '화해의 공원은 이번 행사 기간 동안 며칠 동안 운영되나요? 하루 중 몇 시간 동안 고해 성사가 제공되나요? 청년들이 공원에 자유롭게 드나들 수 있나요? 로마에서 열린 희년 행사 당시에는 고해 성사가 이루어지는 장소로의 접근이 매우 제한적이었고, 거의 통제된 상태였습니다.', '화해의 공원''는 본대회 주간 화요일부터 금요일까지 오후 1시부터 5시까지 진행됩니다.
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q138', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'e'), 137 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '호텔에 묵는 경우, 교리교육 장소로 가는 길을 어떻게 안내받을 수 있나요?', '호텔 등 숙소를 직접 마련한 그룹도 배정된 교리교육 장소를 기준으로 이동하시면 됩니다. 교리교육 장소와 이동에 필요한 안내는 추후 공지할 예정입니다.' FROM qa_item WHERE question_no = 'Q138' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q139', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'e'), 138 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '파나마에서는 사전 행사와 본 행사 전에 교리교육 자료를 제공해 주었습니다. 이번에도 그럴까요?', '가능하면 본행사 전에 제공되리라 생각합니다.' FROM qa_item WHERE question_no = 'Q139' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q140', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'e'), 139 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '숙소가 서울에서 다소 떨어져 있는 경우에도 숙소 위치를 고려하여 가장 가까운 교리교육 장소로 배정받을 수 있나요?', '숙소에서 교리교육 장소까지의 경로와 소요 시간은 숙소 위치에 따라 달라지므로, 안내받은 장소의 주소를 기준으로 지도 앱 등을 통해 확인해 주시기 바랍니다.' FROM qa_item WHERE question_no = 'Q140' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q141', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'e'), 140 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교리교육은 어떻게 신청하며, 리스본 떄와 같이 참여형·역동적인 프로그램으로 진행될 예정인가요?', '교리교육은 강사 선정 후 참여 인원을 예상하여 진행할 예정입니다. 리스본과 비슷하게 진행될 것이라 예상합니다.' FROM qa_item WHERE question_no = 'Q141' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
