INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교리 교육 시간에 사용할 언어들을 알려 주실 수 있나요?', '6개 공식언어로 진행되리라 예상합니다.' FROM qa_item WHERE question_no = 'Q142' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
