INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교리교육 장소는 언제 확정·안내되나요?', '대회 약 1개월 전 시점 부터 순차적으로 확정되어 메일로 안내될 예정입니다.' FROM qa_item WHERE question_no = 'Q143' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
