INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '전체 등록 인원이 교리교육 장소의 수용 가능 인원을 초과할 경우, 모든 순례자가 교리교육에 참여할 수 있도록 어떤 방식으로 장소와 수용 인원을 확보·배정할 예정인가요?', '교리교육 장소는 지속적으로 확인 중에 있으며, 교리 교육을 신청한 참가자 모두 교육을 받을 수 있도록 최선을 다할 것입니다.' FROM qa_item WHERE question_no = 'Q144' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q145', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'e'), 144 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교리교육을 기획하고자 할 때 미리 알려야 하나요?', '교리교육의 강사와 주제는 DLFL에서 선정합니다.' FROM qa_item WHERE question_no = 'Q145' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO qa_item (question_no, section_id, topic_id, subtopic_id, sort_order) SELECT 'Q146', s.id, t.id, (SELECT st.id FROM qa_subtopic st WHERE st.topic_id = t.id AND st.code = 'e'), 145 FROM qa_section s JOIN qa_topic t ON t.section_id = s.id AND t.no = '2' WHERE s.code = 'Ⅳ' ON CONFLICT (question_no) DO UPDATE SET section_id = EXCLUDED.section_id, topic_id = EXCLUDED.topic_id, subtopic_id = EXCLUDED.subtopic_id, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO qa_item_i18n (item_id, lang, question, answer) SELECT id, 'ko', '교리교육 진행자로 참여하려면 어떻게 해야 하나요?', '교리교육에 관련하여 DLFL과 논의를 진행하면서 안내하도록 하겠습니다.' FROM qa_item WHERE question_no = 'Q146' ON CONFLICT (item_id, lang) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, updated_at = now();
INSERT INTO opinion (no, topic, content, sort_order) VALUES (1, '숙소', '같은 숙소에서 화장실 하나당 25명이라니, 조금 부족해 보입니다.', 0) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (2, '숙소', '한 대표단이 자체적으로 호텔에 숙박할 경우, 나눔(교류)의 경험이 덜 풍성해질 수 있지 않을까요? 어떤 방안을 권장하시나요?', 1) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (3, '체크인', '동일한 매크로그룹 내 숙박 포함·미포함 하위그룹이 함께 체크인할 수 있나요? 순례자 센터가 하나뿐이라 하위그룹들이 서로 다른 장소를 오가면 혼란스러울 수 있어 걱정됩니다.', 2) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (4, '조직위원회 관련', '청년 순례자가 자국에서 개최국으로 왔다가 돌아가지 않고 이주민이나 난민 신청자가 되는 경우, 교회적 측면과 정부적 측면에서 각각 어떤 장단점이 있나요?', 3) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (5, '조직위원회 관련', '개신교 청년들을 포함하는 근거는 교회의 에큐메니즘(일치 운동) 교리에 어긋납니다. 그리스도인 청년을 조종하여 가톨릭으로 개종시키려는 것은 교회의 종교 간 대화 원칙에 위배됩니다. 이를 수정하시어 개신교 청년들을 ''소품''처럼 이용하지 마시고 그들에게 합당한 존엄성을 갖고 대해주시기 바랍니다.', 4) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (6, '조직위원회 관련', '많은 젊은이들에게 WYD는 전 세계의 다양한 언어와 문화를 접하는 진정한 경험입니다. 하지만 이는 또한 아프리카나 중동 국가 중 한 곳에서 열릴 수도 있는 WYD를 앞두고, 그리고 바로 이곳 서울에서 열리는 이번 대회를 통해, 동방 가톨릭 교회들의 참여를 통해 교회의 보편성을 어떻게 더 구체적으로 구현할 수 있을지 보여주는 가톨릭 교회의 경험이기도 합니다.', 5) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (7, '조직위원회 관련', 'WYD에 물리적으로 참가가 불가한 순례자들의 경우 대회에 어떻게 참여할 수 있을지', 6) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (8, '[본대회] 개막미사·교황 환영행사·십자가의 길', '“안”과 “밖”에 대한 심리적 인식은 중요합니다. 경기장의 경계가 정해지면, 평화공원에 있는 사람들은 자연스럽게 주요 행사가 경기장 안에서 진행되고 있다는 사실을 알게 될 것입니다. 경기장 밖에서 아무리 훌륭한 프로그램을 진행하더라도 이러한 인식을 없애기는 어려울 수 있습니다.', 7) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (9, '[본대회] 개막미사·교황 환영행사·십자가의 길', '서울 월드컵 경기장에 대해 우려하고 있습니다. 좌석 배정이 공평하더라도 물리적 장벽 자체가 배제를 암시할 수 있습니다. 대규모 대표단의 경우, 왜 어떤 사람들은 경기장에 들어가고 다른 사람들은 화면으로 봐야 하는지 설명하기 어려울 것입니다. 청년들은 참석을 꺼릴 수도 있습니다. 다른 사람들이 경기장 안에 있는 동안 멀리서 화면으로 봐야 한다면, 이는 의욕을 꺾게 될 것입니다. 재고해 주시기를 바랍니다.', 8) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (10, '[본대회] 개막미사·교황 환영행사·십자가의 길', '경기장 방식이 수용 인원 제한 문제를 해결하기보다는 그저 관리하는 데 그친다는 점에 대해 여전히 깊은 우려를 가지고 있습니다. 로테이션과 평화공원 방식이 공정할 수는 있겠지만, 많은 순례자들은 여전히 주요 행사에서 소외감을 느낄 것입니다. 청년들은 WYD에 참석하기 위해 큰 희생을 치릅니다. 만약 그들이 행사에 온전히 참여하지 못한다면, 많은 사람들이 당연히 “가는 게 무슨 의미가 있는가?”라고 물을 것입니다.', 9) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (11, '[본대회] 개막미사·교황 환영행사·십자가의 길', '제안된 경기장 시스템은 수용 인원 문제를 해결하기보다는 입장 제한을 관리하는 데 초점을 맞추고 있습니다. “3회 순환 / 중복 배정 금지” 방식은 경기장 입장 기회를 공정하게 배분할 수는 있겠지만, 그럼에도 불구하고 많은 등록된 순례자들이 특정 행사가 열리는 주 경기장 내부에서 행사에 참여하지 못하게 될 것입니다.', 10) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (12, '[본대회] 개막미사·교황 환영행사·십자가의 길', '경기장 - 혼잡과 혼란이 발생할까 우려됩니다. 각 행사마다 출입 경로가 다른 상황에서 수많은 순례자들을 경기장과 평화 공원 사이로 순환시키다 보면, 인파 이동과 의사소통에 큰 어려움이 생길 수 있습니다. 수십만 명이 한꺼번에 이동하는 상황에서 사소한 오해조차도 순식간에 안전 및 사목적 문제로 번질 수 있습니다.', 11) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO opinion (no, topic, content, sort_order) VALUES (13, '[본대회] 전례', '전례에 각별한 주의를 기울여 주시기 바랍니다. 가능하다면 대상자가 젊은이들이라는 점을 고려해 주시기 바랍니다. 희년 행사 이후, 젊은이들과 인솔자들은 전례가 세심하게 준비되고 새로운 세대를 배려할 수 있도록(찬양, 제스처, 침묵 등에서…) 요청해 왔습니다.', 12) ON CONFLICT (no) DO UPDATE SET topic = EXCLUDED.topic, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
